#include <iostream>
#include <iomanip>

int main() {
    int total{0};       // accumulator initialized to avoid garbage values
    int gradeCounter{0}; // count of inputs
    int grade{0};

    // Sentinel-controlled loop: -1 indicates end of data entry
    while (std::cin >> grade && grade != -1) {
        total += grade; // compound assignment operator
        ++gradeCounter;
    }

    if (gradeCounter != 0) {
        // Explicit type cast ensures floating-point division instead of integer truncation
        double average = static_cast<double>(total) / gradeCounter;

        std::cout << "Total: " << total << "\n";
        std::cout << "Count: " << gradeCounter << "\n";
        // std::fixed and std::setprecision(2) mirror printf("%.2f") rounding behavior
        std::cout << "Class average is " << std::fixed << std::setprecision(2) << average << "\n";
    } else {
        std::cout << "No grades were entered.\n";
    }

    return 0;
}

#include <iostream>
#include <climits>

int main() {
    // 1. Prefix vs. Postfix demonstration
    int c = 5;
    std::cout << "Initial c = " << c << "\n";
    std::cout << "Post-increment (c++): " << c++ << " (printed before increment)\n";
    std::cout << "After post-increment: " << c << "\n";
    std::cout << "Pre-increment (++c):  " << ++c << " (incremented before printing)\n";
    std::cout << "Final c = " << c << "\n";

    // 2. Industrial-strength overflow check
    int a = INT_MAX - 10;
    int b = 15;

    std::cout << "INT_MAX is: " << INT_MAX << "\n";
    std::cout << "Attempting to add a = " << a << " and b = " << b << "\n";

    // Check if a + b would overflow INT_MAX without actually triggering overflow
    if (b > INT_MAX - a) {
        std::cout << "SECURITY ALERT: Addition would cause arithmetic overflow! Calculation aborted.\n";
    } else {
        int sum = a + b;
        std::cout << "Sum: " << sum << "\n";
    }

    return 0;
}
